function tokenize(text) {
  const m = (text || '').toLowerCase().match(/[а-яёa-z0-9]+/g) || [];
  return m.filter(t => t.length > 2 && !STOPWORDS.has(t));
}
function keywordTop1(question, docs) {
  const qTokens = new Set(tokenize(question));
  const scored = docs.map(doc => {
    const dTokens = new Set(tokenize(doc.text));
    let overlap = 0; for (const t of qTokens) if (dTokens.has(t)) overlap++;
    return {id: doc.id, text: doc.text, overlap};
  });
  scored.sort((a,b) => b.overlap - a.overlap);
  return {top: scored[0], all: scored};
}
const payload = JSON.parse($input.first().json.payload);
const {top} = keywordTop1(payload.question, payload.source_a);
return [{json: {
  question: payload.question,
  source_a: payload.source_a,
  source_b: payload.source_b,
  iteration: payload.iteration || 1,
  reformulated: payload.reformulated || false,
  top_doc_id: top.id, top_doc_text: top.text, top_overlap: top.overlap,
  retrieval_source: 'А'
}}];

