const d = $('Поиск top-1 в источнике А (keyword)').first().json;
const resp = $input.first().json;
let content = null; try { content = resp.choices[0].message.content; } catch(e) {}
let verdict = 'INCORRECT';
let reason = 'не удалось разобрать ответ грейдера — применён безопасный дефолт (fail-closed, см. бриф §2)';
if (content) {
  const m = content.match(/\{[\s\S]*\}/);
  if (m) {
    try {
      const parsed = JSON.parse(m[0]);
      if (['CORRECT','AMBIGUOUS','INCORRECT'].includes(parsed.verdict)) {
        verdict = parsed.verdict; reason = parsed.reason || '';
      }
    } catch(e) {}
  }
}
return [{json: {...d, grader_verdict: verdict, grader_reason: reason, grader_raw: content}}];

